begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create temp table candidate_test(event_id uuid,group_id uuid,pub_id uuid,run_id uuid,stop_id uuid,version integer,portal_id uuid,source_node uuid,portal_node uuid,parent_before jsonb,options jsonb,result jsonb,target_id uuid,first_version integer,finale_reservation jsonb);
insert into candidate_test(event_id,group_id) select event_id,id from app_private.walking_groups where id='23000000-0000-0000-0000-000000000001';
grant all on candidate_test to authenticated;
update app_private.portal_windows set opens_at=now()-interval '1 hour',closes_at=now()+interval '5 hours';
update app_private.start_slots set starts_at=now()-interval '1 minute';
update app_private.event_route_settings set first_start_at=now()-interval '2 hours',global_ordinary_stop_at=now()+interval '2 hours',
 allowed_personal_stop_times=array[now()+interval '1 hour'],ordinary_visit_seconds=60,route_buffer_seconds=0,
 final_portal_id='12000000-0000-0000-0000-000000000030',finale_opens_at=now()-interval '1 hour',finale_last_arrival_at=now()+interval '4 hours',
 finale_closes_at=now()+interval '5 hours',finale_show_seconds=60,finale_turnover_seconds=120,finale_max_concurrent_groups=10,finale_max_concurrent_children=40,finale_available=true,planner_mode='dynamic'
 where event_id=(select event_id from candidate_test);
with inserted as (insert into app_private.group_schedule_revisions(group_id,revision,state,start_slot_id,effective_ordinary_stop_at,expected_finale_arrival_at,preference_match,published_at)
 select group_id,1,'published',g.start_slot_id,now()+interval '2 hours',now()+interval '1 hour','neutral',now() from candidate_test t join app_private.walking_groups g on g.id=t.group_id returning id)
 update app_private.walking_groups wg set route_mode='dynamic',current_schedule_revision_id=inserted.id,desired_ordinary_visits=3,version=version+1 from inserted where wg.id=(select group_id from candidate_test);
update candidate_test set pub_id=(select id from app_private.group_start_publications where group_id=candidate_test.group_id and schedule_id is not null order by publication_order desc limit 1);
select ok((app_private.start_ops_route_preview((select group_id from candidate_test))->>'feasible')::boolean,'confirmed published preparation has a feasible actual preview');
select is((app_private.start_ops_route_preview((select group_id from candidate_test))->>'calculatedFromAt')::timestamptz,(select starts_at from app_private.group_start_publications where id=(select pub_id from candidate_test)),'preparation clock stays at the frozen appointment');
select ok((select count(*)<=3 and count(*)>0 from jsonb_array_elements(app_private.start_ops_route_preview((select group_id from candidate_test))->'stops') s where s->>'kind'='ordinary'),'explicit visit limit caps ordinary preparation stops');
select set_config('request.jwt.claims','{"sub":"c0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
update candidate_test set run_id=(api.run_start(group_id,array(select (v->>'registrationChildId')::uuid from jsonb_array_elements(api.group_roster(group_id)) v),(api.group_snapshot(group_id)#>>'{group,version}')::integer,'candidate-real-start','candidate-real-start')->>'runId')::uuid;
update candidate_test set parent_before=api.group_snapshot(group_id),stop_id=(api.group_snapshot(group_id)#>>'{run,currentStop,id}')::uuid,version=(api.group_snapshot(group_id)#>>'{run,version}')::integer,portal_id=(api.group_snapshot(group_id)#>>'{run,currentStop,portal,id}')::uuid;
select throws_ok($$select api.admin_route_command_options(run_id) from candidate_test$$,'42501','NOT_AUTHORIZED','parent cannot enumerate other candidate addresses or adults');
select set_config('request.jwt.claims','{"sub":"f0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
update candidate_test set options=api.admin_route_command_options(run_id);
select is((select (options->>'runVersion')::integer from candidate_test),(select version from candidate_test),'command options carry the actual run version');
select is((select jsonb_array_length(options->'adults') from candidate_test),1,'responsible adults come from this actual registered household');
select is((select options#>>'{adults,0,userId}' from candidate_test),'a0000000-0000-0000-0000-000000000001','responsible choice is an actual registered household adult');
select ok(not (select (p->>'eligible')::boolean from candidate_test t cross join lateral jsonb_array_elements(t.options->'portals') p where p->>'id'=t.portal_id::text),'current physical destination is not offered as a replacement');
update candidate_test set target_id='12000000-0000-0000-0000-000000000002';
select ok((select (p->>'eligible')::boolean from candidate_test t cross join lateral jsonb_array_elements(t.options->'portals') p where p->>'id'=t.target_id::text),'verified next house has real feasible ETA and capacity');
select throws_ok($$select api.admin_redirect_group(run_id,'ordinary',target_id,version-1,'Een achterhaalde keuze mag niet worden toegepast') from candidate_test$$,'40001','STALE_VERSION','stale command cannot replace the released stop');
set local role postgres;
select is(app_private.start_ops_route_preview((select group_id from candidate_test))#>>'{stops,0,id}',(select stop_id::text from candidate_test),'live preview retains the original current stop ID');
select ok((app_private.start_ops_route_preview((select group_id from candidate_test))->>'calculatedFromAt')::timestamptz>=(select (parent_before#>>'{group,start,startsAt}')::timestamptz+interval '30 seconds' from candidate_test),'live preview uses actual now, not the old departure instant');
select ok((select count(*)<=3 and count(*)>0 from jsonb_array_elements(app_private.start_ops_route_preview((select group_id from candidate_test))->'stops') s where s->>'kind'='ordinary'),'current destination consumes its future visit position only once');
update app_private.portals set operation_status='closed' where id=(select target_id from candidate_test);
set local role authenticated;
select throws_ok($$select api.admin_redirect_group(run_id,'ordinary',target_id,version,'De inmiddels gesloten poort moet worden geweigerd') from candidate_test$$,'23514','PREFERRED_PORTAL_UNAVAILABLE','fresh server assessment rejects a house closed after the dialog opened');
select is(api.group_snapshot((select group_id from candidate_test))#>>'{run,currentStop,id}',(select stop_id::text from candidate_test),'failed redirect preserves the original released destination');
update candidate_test set options=api.admin_route_command_options(run_id);
select ok(not (select (p->>'eligible')::boolean from candidate_test t cross join lateral jsonb_array_elements(t.options->'portals') p where p->>'id'=t.target_id::text),'refreshed choices explain the now unavailable house');
select ok((select (p->'reasons') ? 'Deze poort ontvangt geen nieuwe groepen.' from candidate_test t cross join lateral jsonb_array_elements(t.options->'portals') p where p->>'id'=t.target_id::text),'closed-house reason is concrete Dutch text');
set local role postgres;
update app_private.portals set operation_status='open' where id=(select target_id from candidate_test);
set local role authenticated;
update candidate_test set first_version=version,result=api.admin_redirect_group(run_id,'ordinary',target_id,version,'Organisatie kiest een passend bereikbaar volgend huis');
select is(api.group_snapshot((select group_id from candidate_test))#>>'{run,currentStop,portal,id}',(select target_id::text from candidate_test),'actual command reserves and releases exactly the selected physical house');
select is((select api.admin_redirect_group(run_id,'ordinary',target_id,first_version,'Organisatie kiest een passend bereikbaar volgend huis') from candidate_test),(select result from candidate_test),'lost-response retry returns the original successful redirect result');
set local role postgres;
select is((select count(*)::integer from app_private.audit_events where action='group.destination_redirected' and resource_id=(select run_id from candidate_test)),1,'retry does not create another redirect audit');
select is((select count(*)::integer from app_private.run_stops where run_id=(select run_id from candidate_test) and state='active'),1,'retry leaves one active released instruction');
select is(app_private.evening_route_context((select group_id from candidate_test))->>'completedOrdinaryVisits','0','unscanned redirected house does not fabricate a visit');
select is(jsonb_array_length(app_private.start_ops_route_preview((select group_id from candidate_test))->'history'),1,'redirected instruction remains separate history');
select is(app_private.start_ops_route_preview((select group_id from candidate_test))#>>'{history,0,arrivalConfirmed}','false','system skip is explicitly not a confirmed arrival');
update candidate_test set finale_reservation=(select to_jsonb(b) from app_private.portal_reservations b where b.start_publication_id=candidate_test.pub_id);
set local role authenticated;
update candidate_test set version=(api.group_snapshot(group_id)#>>'{run,version}')::integer;
update candidate_test set result=api.admin_redirect_group(run_id,'finale',null,version,'Organisatie kiest bewust voor de vaste finale-afspraak');
select is(api.group_snapshot((select group_id from candidate_test))#>>'{run,waitingReason}','finale_window','manual finale choice waits for its own fixed departure time');
select is(api.group_snapshot((select group_id from candidate_test))#>'{run,currentStop}','null'::jsonb,'waiting choice does not reveal an early finale address');
set local role service_role;
select lives_ok($$select api.worker_dispatch_due_groups('duindorp-halloween-2026',50)$$,'later worker honors the persistent finale choice');
set local role postgres;
select ok((select finale_only from app_private.group_runs where id=(select run_id from candidate_test)),'explicit finale-only preference remains durable');
select is((select current_stop_id from app_private.group_runs where id=(select run_id from candidate_test)),null::uuid,'worker does not replace finale waiting with an ordinary house');
select is((select to_jsonb(b) from app_private.portal_reservations b where b.start_publication_id=(select pub_id from candidate_test)),(select finale_reservation from candidate_test),'manual finale choice and worker preserve exact reservation ID, time and content');
select is((select count(*)::integer from jsonb_array_elements(app_private.start_ops_route_preview((select group_id from candidate_test))->'stops') s where s->>'kind'='ordinary'),0,'remaining preview also respects the explicit finale-only choice');
select is((select count(*)::integer from app_private.run_stop_arrivals where run_id=(select run_id from candidate_test)),0,'all management choices preserve the absence of actual arrival evidence');
select ok(not has_function_privilege('authenticated','app_private.evening_route_candidates(jsonb,uuid,timestamptz,uuid[],integer,uuid)','execute'),'shared private candidate planner cannot enumerate house addresses');
insert into app_private.event_capabilities(event_id,user_id,capability,granted_by) select event_id,'b0000000-0000-0000-0000-000000000001','groups_manage','f0000000-0000-0000-0000-000000000001' from candidate_test;
select set_config('request.jwt.claims','{"sub":"b0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select ok(not (api.admin_route_command_options((select run_id from candidate_test))#>>'{withdraw,eligible}')::boolean,'group-only manager sees the actual separate safe-withdrawal permission');
select throws_ok($$select api.admin_safe_withdraw_group(run_id,'a0000000-0000-0000-0000-000000000001',version,'Groepen beheren verleent niet automatisch avondregiebevoegdheid') from candidate_test$$,'42501','NOT_AUTHORIZED','group-only management cannot bypass safe-withdrawal authorization');
set local role postgres;
select * from finish();
rollback;
